/**
 * 费用档案：类别树 + 费用项目的默认数据（来自旧程序的费用档案，已合并其后续补丁并去掉作废项），以及“挂账节点”定义。
 * 导入是按编号幂等的：重复导入只补缺，不覆盖已有改动。
 */

/** 挂账节点：一笔费用“记在谁头上”。有对应资料表的可以选具体对象，没有的只写名字。 */
export const FEE_BOOKING_NODES: ReadonlyArray<{ node: string; resource: string | null; kind?: string }> = [
  { node: '公司', resource: null },
  { node: '部门', resource: null },
  { node: '人员', resource: null },
  { node: '营业执照', resource: 'licenses' },
  { node: '税务', resource: 'tax-profiles' },
  { node: '商标', resource: 'trademarks' },
  { node: '店铺', resource: 'stores' },
  { node: '手机号', resource: 'phones' },
  { node: '宽带账号', resource: 'broadband' },
  { node: '自媒体账号', resource: 'self-media' },
  { node: '账号与服务备忘', resource: 'memos' },
  { node: '公司公户', resource: 'bank-accounts', kind: 'company_public' },
  { node: '公司银行卡', resource: 'bank-accounts', kind: 'company_card' },
  { node: '公司出纳账户', resource: 'bank-accounts', kind: 'cashier_account' },
  { node: '店铺公户', resource: 'bank-accounts', kind: 'store_public' },
  { node: '店铺个人银行卡', resource: 'bank-accounts', kind: 'store_personal_card' },
  { node: '固定资产', resource: 'fixed-assets' },
  { node: '房间与档案位置', resource: 'locations' },
  { node: '仓库', resource: 'finance-warehouses' },
  { node: '商品', resource: 'finance-products' },
  { node: '供应商', resource: 'finance-suppliers' },
  { node: '客户', resource: 'finance-customers' },
  { node: '快递网点', resource: null },
  { node: '项目', resource: null },
  { node: '不固定', resource: null },
];
export const FEE_BOOKING_NODE_MAP = new Map(FEE_BOOKING_NODES.map((n) => [n.node, n]));

/** 旧默认费用项里的老写法 → 现在的挂账节点（旧程序里“公户”指公司银行公户） */
export const FEE_BOOKING_NODE_ALIASES: Readonly<Record<string, string>> = { 公户: '公司公户' };

/** 把“a、b”形式的挂账节点文字规范成合法节点列表：老写法转换、去重、丢掉不认识的 */
export function normalizeFeeBookingNodes(text: string): string[] {
  const out: string[] = [];
  for (const raw of text.split(/[、,，]/)) {
    const n = FEE_BOOKING_NODE_ALIASES[raw.trim()] ?? raw.trim();
    if (n && FEE_BOOKING_NODE_MAP.has(n) && n !== '不固定' && !out.includes(n)) out.push(n);
  }
  return out;
}

